#include <bits/stdc++.h>
using namespace std;

bool isPoligrama(const string& s, int len) {
    int n = (int)s.size();
    int parts = n / len;

    int base[26] = {};
    for (int i = 0; i < len; ++i) {
        base[s[i] - 'a']++;
    }

    for (int p = 1; p < parts; ++p) {
        int cnt[26] = {};
        int start = p * len;
        for (int i = start; i < start + len; ++i) {
            cnt[s[i] - 'a']++;
        }
        for (int c = 0; c < 26; ++c) {
            if (cnt[c] != base[c]) {
                return false;
            }
        }
    }

    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    for (int len = 1; len * 2 <= n; ++len) {
        if (n % len == 0 && isPoligrama(s, len)) {
            cout << s.substr(0, len) << '\n';
            return 0;
        }
    }

    cout << "*\n";
    return 0;
}
